const ordersById = { 'ORD-1': { status: 'active' }, 'ORD-2': { status: 'active' } };

function cancelOrder(orderId) {
  if (ordersById[orderId]) {
    ordersById[orderId].status = 'cancelled';
    return `已取消訂單 ${orderId}`;
  }
  return `找不到訂單 ${orderId}`;
}

const customerId = 'ORD-2';
console.log(cancelOrder(customerId));

