function sameAddress(a, b) {
  return a.street === b.street && a.city === b.city && a.zip === b.zip;
}

const address1 = { street: '中山路 1 號', city: '台北', zip: '100' };
const address2 = { street: '中山路 1 號', city: '台北', zip: '100' };

console.log(address1 === address2, sameAddress(address1, address2));

